html:
{#- 80 mm thermal packing slip for the warehouse. No prices. -#}
<style>
	.slip { width: 72mm; font-family: "Courier New", monospace; font-size: 11px; }
	.slip h2 { font-size: 14px; margin: 0 0 4px; text-align: center; }
	.slip .c { text-align: center; }
	.slip hr { border: 0; border-top: 1px dashed #000; margin: 4px 0; }
	.slip table { width: 100%; }
	.slip td { vertical-align: top; padding: 1px 0; }
	.slip .big { font-size: 13px; font-weight: bold; }
</style>
<div class="slip">
	<h2>PACKING SLIP</h2>
	<div class="c">{{ doc.company }}</div>
	<hr>
	<div>Invoice: <b>{{ doc.name }}</b></div>
	<div>Date: {{ frappe.format(doc.posting_date, "Date") }}</div>
	{% if doc.items[0].delivery_note %}<div>DN: {{ doc.items[0].delivery_note }}</div>{% endif %}
	<div>Ship to: <b>{{ doc.customer_name }}</b></div>
	<div>{{ (doc.shipping_address or doc.address_display or "") | striptags | truncate(90) }}</div>
	<hr>
	<table>
		{%- for row in doc.items %}
		<tr><td colspan="2" class="big">{{ row.item_code }}</td></tr>
		<tr><td>{{ row.item_name | truncate(28) }}</td><td style="text-align:right" class="big">{{ row.qty | int if row.qty == row.qty | int else row.qty }} {{ row.uom }}</td></tr>
		{% if row.serial_no %}<tr><td colspan="2">S/N {{ row.serial_no | replace("\n", " ") }}</td></tr>{% endif %}
		{% if row.batch_no %}<tr><td colspan="2">Batch {{ row.batch_no }}</td></tr>{% endif %}
		<tr><td colspan="2">[ ] picked  [ ] packed</td></tr>
		{%- endfor %}
	</table>
	<hr>
	<div>Packages: ______  Weight: ______ kg</div>
	<div>Packed by: ____________</div>
	<div>Checked by: ___________</div>
	<hr>
	<div class="c">Total lines: {{ doc.items | length }}</div>
</div>
